61	export const extractUploadedUrl = (
62	  uploadReturn: string,
63	): string | undefined => {
64	  const trimmed = uploadReturn.trim();
65	  for (const pattern of UPLOAD_RETURN_PATTERNS) {
66	    const url = trimmed.match(pattern)?.[1];
67	    if (url) return url;
68	  }
69	  return undefined;
70	};
71	
72	/**
73	 * An extension for the uploaded file, so Roam serves it as the type it is.
74	 *
75	 * Taken from the recorded name where there is one, since that is what the publisher saw,
76	 * and derived from the MIME subtype otherwise. Neither is guaranteed, and an asset with
77	 * no extension still uploads and still renders for the types Roam sniffs.
78	 */
79	const EXTENSION_CHARACTERS = /^[a-z0-9]+$/i;
80	
81	const extensionFor = ({
82	  sourcePath,
83	  mimetype,
84	}: {
85	  sourcePath?: string | null;
86	  mimetype?: string;
87	}): string => {
88	  const leaf = sourcePath?.split("/").pop() ?? "";
89	  const dot = leaf.lastIndexOf(".");
90	  // A dot in the stem is not an extension: `2024.06.01 meeting` would otherwise upload as
91	  // `.06.01 meeting`. Anything that does not look like an extension falls through to the
92	  // MIME type, which is the better guess precisely in that case.
93	  const named = dot > 0 ? leaf.slice(dot + 1) : "";
94	  if (EXTENSION_CHARACTERS.test(named)) return `.${named}`;
95	
96	  // `image/svg+xml` carries its useful part before the `+`; anything else non-alphanumeric
97	  // is not an extension we should be inventing.
98	  const subtype = mimetype?.split("/")[1]?.split("+")[0] ?? "";
99	  return EXTENSION_CHARACTERS.test(subtype) ? `.${subtype}` : "";
100	};
101	
102	/**
103	 * `imported-<sha256>`, which is what makes the registry a cache rather than a source of
104	 * truth: the hash travels with the file, so a lost registry can be rebuilt by reading
105	 * the names of the files a graph already holds.
106	 */
107	export const mirroredAssetFileName = ({
108	  contentHash,
109	  sourcePath,
110	  mimetype,
111	}: {
112	  contentHash: string;
113	  sourcePath?: string | null;
114	  mimetype?: string;
115	}): string =>
116	  `imported-${contentHash}${extensionFor({ sourcePath, mimetype })}`;
117	
118	/**
119	 * Copies one asset out of shared storage and into this graph's own Roam storage.
120	 *
121	 * Roam renders an embed by issuing an anonymous cross-origin GET, with no credentials,
122	 * so whatever an imported page points at has to be fetchable without our auth. Shared
123	 * storage is private, so the bytes have to land somewhere public: this graph's own
124	 * Firebase storage, through `file.upload`.
125	 *
126	 * Every asset takes this path, whatever platform published it, including a Roam-origin
127	 * one imported into a second graph. Skipping the copy for those would put origin
128	 * detection back into the destination, and would leave this graph's page depending on a
129	 * blob the origin graph's owner can delete. The copy is irrevocable, deliberately.
130	 *
131	 * **Nothing rolls an upload back.** `file.delete` takes a URL, so a caller could undo its
132	 * own upload, but must not: users of a graph share one registry keyed by content hash (see
133	 * `assetRegistry`), so another user's import may already have resolved this blob. A failed
134	 * import leaves its copies in place, so callers should reject an import before uploading
135	 * when they can. Roam exposes no way to list a graph's files, so an orphan cannot be swept
136	 * up afterwards either.
137	 *
138	 * **Call this one asset at a time.** The registry read and the matching write are
139	 * separated by a download and an upload, so callers running it under `Promise.all` all
140	 * see an empty registry for the same hash: the bytes upload once per call, the registry
141	 * keeps one URL, and the rest are permanent orphans in the user's Roam storage. The
142	 * mitigation is the caller's sequential loop. Parallelising a caller means adding an
143	 * in-flight map of hash to promise here first.
144	 */
145	export const mirrorAssetToRoamStorage = async ({
146	  client,
147	  contentHash,
148	  sourcePath,
149	}: {
150	  client: DGSupabaseClient;
151	  contentHash: string;
152	  /** The name the reference records, used only to give the upload an extension. */
153	  sourcePath?: string | null;
154	}): Promise<AssetMirrorResult> => {
155	  const alreadyMirrored = readMirroredAssetUrl(contentHash);
156	  if (alreadyMirrored)
157	    return { status: "reused", contentHash, url: alreadyMirrored };
158	
159	  const storage = client.storage.from(SHARED_ASSET_BUCKET);
160	
161	  // Size is read from the object's metadata rather than from the downloaded bytes, so an
162	  // oversized asset costs one small request instead of the download this cap exists to
163	  // prevent. Where the metadata omits it, the check moves after the download.
164	  //
165	  // An info failure is metadata this object does not carry, not a reason to abort: the
166	  // pre-check is only an optimisation, and the post-download check enforces the cap on
167	  // its own. Where info fails for a reason that matters — a missing object, a policy that
168	  // denies reads — the download fails next and reports it there.
169	  const { data: info } = await storage.info(contentHash);
170	  const tooLarge = (size: number): SkippedMirror => ({
171	    status: "skipped",
172	    contentHash,
173	    reason: "too-large",
174	    size,
175	    limit: MAX_ASSET_BYTES,
176	  });
177	  if (info?.size !== undefined && isAssetTooLarge(info.size))
178	    return tooLarge(info.size);
179	
180	  const { data: blob, error: downloadError } =
181	    await storage.download(contentHash);
182	  if (downloadError) throw downloadError;
183	  if (!blob)
184	    throw new Error(`No bytes in shared storage for asset ${contentHash}`);
185	  if (isAssetTooLarge(blob.size)) return tooLarge(blob.size);
186	
187	  const mimetype = info?.contentType || blob.type || undefined;
188	  const file = new File(
189	    [blob],
190	    mirroredAssetFileName({ contentHash, sourcePath, mimetype }),
191	    mimetype ? { type: mimetype } : undefined,
192	  );
193	
194	  // Upload first, then record. A placeholder written beforehand would carry no URL, so a
195	  // later run could neither reuse the upload nor find it, and Roam exposes no way to list
196	  // a graph's files. A crash between the two leaves one orphaned file, which Roam's own
197	  // documentation treats as normal.
198	  const uploadReturn = await window.roamAlphaAPI.file.upload({
199	    file,
200	    // One import mirrors one file per distinct hash across every node it brings in, so
201	    // the default toast would fire dozens of times at a user who asked for one import.
202	    toast: { hide: true },
203	  });
204	  const url = extractUploadedUrl(uploadReturn);
205	  if (!url)
206	    throw new Error(
