export const extractUploadedUrl = (
  uploadReturn: string,
): string | undefined => {
  const trimmed = uploadReturn.trim();
  for (const pattern of UPLOAD_RETURN_PATTERNS) {
    const url = trimmed.match(pattern)?.[1];
    if (url) return url;
  }
  return undefined;
};

/**
 * An extension for the uploaded file, so Roam serves it as the type it is.
 *
 * Taken from the recorded name where there is one, since that is what the publisher saw,
 * and derived from the MIME subtype otherwise. Neither is guaranteed, and an asset with
 * no extension still uploads and still renders for the types Roam sniffs.
 */
const EXTENSION_CHARACTERS = /^[a-z0-9]+$/i;

const extensionFor = ({
  sourcePath,
  mimetype,
}: {
  sourcePath?: string | null;
  mimetype?: string;
}): string => {
  const leaf = sourcePath?.split("/").pop() ?? "";
  const dot = leaf.lastIndexOf(".");
  // A dot in the stem is not an extension: `2024.06.01 meeting` would otherwise upload as
  // `.06.01 meeting`. Anything that does not look like an extension falls through to the
  // MIME type, which is the better guess precisely in that case.
  const named = dot > 0 ? leaf.slice(dot + 1) : "";
  if (EXTENSION_CHARACTERS.test(named)) return `.${named}`;

  // `image/svg+xml` carries its useful part before the `+`; anything else non-alphanumeric
  // is not an extension we should be inventing.
  const subtype = mimetype?.split("/")[1]?.split("+")[0] ?? "";
  return EXTENSION_CHARACTERS.test(subtype) ? `.${subtype}` : "";
};

/**
 * `imported-<sha256>`, which is what makes the registry a cache rather than a source of
 * truth: the hash travels with the file, so a lost registry can be rebuilt by reading
 * the names of the files a graph already holds.
 */
export const mirroredAssetFileName = ({
  contentHash,
  sourcePath,
  mimetype,
}: {
  contentHash: string;
  sourcePath?: string | null;
  mimetype?: string;
}): string =>
  `imported-${contentHash}${extensionFor({ sourcePath, mimetype })}`;

/**
 * Copies one asset out of shared storage and into this graph's own Roam storage.
 *
 * Roam renders an embed by issuing an anonymous cross-origin GET, with no credentials,
 * so whatever an imported page points at has to be fetchable without our auth. Shared
 * storage is private, so the bytes have to land somewhere public: this graph's own
 * Firebase storage, through `file.upload`.
 *
 * Every asset takes this path, whatever platform published it, including a Roam-origin
 * one imported into a second graph. Skipping the copy for those would put origin
 * detection back into the destination, and would leave this graph's page depending on a
 * blob the origin graph's owner can delete. The copy is irrevocable, deliberately.
 *
 * **Nothing rolls an upload back.** `file.delete` takes a URL, so a caller could undo its
 * own upload, but must not: users of a graph share one registry keyed by content hash (see
 * `assetRegistry`), so another user's import may already have resolved this blob. A failed
 * import leaves its copies in place, so callers should reject an import before uploading
 * when they can. Roam exposes no way to list a graph's files, so an orphan cannot be swept
 * up afterwards either.
 *
 * **Call this one asset at a time.** The registry read and the matching write are
 * separated by a download and an upload, so callers running it under `Promise.all` all
 * see an empty registry for the same hash: the bytes upload once per call, the registry
 * keeps one URL, and the rest are permanent orphans in the user's Roam storage. The
 * mitigation is the caller's sequential loop. Parallelising a caller means adding an
 * in-flight map of hash to promise here first.
 */
export const mirrorAssetToRoamStorage = async ({
  client,
  contentHash,
  sourcePath,
}: {
  client: DGSupabaseClient;
  contentHash: string;
  /** The name the reference records, used only to give the upload an extension. */
  sourcePath?: string | null;
}): Promise<AssetMirrorResult> => {
  const alreadyMirrored = readMirroredAssetUrl(contentHash);
  if (alreadyMirrored)
    return { status: "reused", contentHash, url: alreadyMirrored };

  const storage = client.storage.from(SHARED_ASSET_BUCKET);

  // Size is read from the object's metadata rather than from the downloaded bytes, so an
  // oversized asset costs one small request instead of the download this cap exists to
  // prevent. Where the metadata omits it, the check moves after the download.
  //
  // An info failure is metadata this object does not carry, not a reason to abort: the
  // pre-check is only an optimisation, and the post-download check enforces the cap on
  // its own. Where info fails for a reason that matters — a missing object, a policy that
  // denies reads — the download fails next and reports it there.
  const { data: info } = await storage.info(contentHash);
  const tooLarge = (size: number): SkippedMirror => ({
    status: "skipped",
    contentHash,
    reason: "too-large",
    size,
    limit: MAX_ASSET_BYTES,
  });
  if (info?.size !== undefined && isAssetTooLarge(info.size))
    return tooLarge(info.size);

  const { data: blob, error: downloadError } =
    await storage.download(contentHash);
  if (downloadError) throw downloadError;
  if (!blob)
    throw new Error(`No bytes in shared storage for asset ${contentHash}`);
  if (isAssetTooLarge(blob.size)) return tooLarge(blob.size);

  const mimetype = info?.contentType || blob.type || undefined;
  const file = new File(
    [blob],
    mirroredAssetFileName({ contentHash, sourcePath, mimetype }),
    mimetype ? { type: mimetype } : undefined,
  );

  // Upload first, then record. A placeholder written beforehand would carry no URL, so a
  // later run could neither reuse the upload nor find it, and Roam exposes no way to list
  // a graph's files. A crash between the two leaves one orphaned file, which Roam's own
  // documentation treats as normal.
  const uploadReturn = await window.roamAlphaAPI.file.upload({
    file,
    // One import mirrors one file per distinct hash across every node it brings in, so
    // the default toast would fire dozens of times at a user who asked for one import.
    toast: { hide: true },
  });
  const url = extractUploadedUrl(uploadReturn);
  if (!url)
    throw new Error(
      `Roam returned an upload result this code cannot read a URL from: ${uploadReturn}`,
    );

  // Best-effort, and never fatal. The bytes are uploaded and the URL is in hand, so
  // throwing here would report a copy that plainly succeeded as a failure. A lost write
  // costs one redundant upload later, which is what `assetRegistry.ts` accepts by being
  // a cache.
  try {
    await recordMirroredAsset({ contentHash, url });
  } catch (error) {
    console.warn(
      `Copied an asset into this graph but could not record it in the asset registry, so it will be uploaded again on the next import: ${getErrorMessage(error)}`,
    );
  }
  return { status: "mirrored", contentHash, url };
};

/**
 * Protects Roam's media embeds from Roam's own markdown parser.
 *
 * `{{[[pdf]]: url}}` is not markdown, so `fromMarkdown` autolinks the URL and swallows the
 * closing `}}`. The braces come back percent-encoded in the link's destination and raw in
 * its text, so the two differ and the block is written as `{{[[pdf]]: [url}}](url%7D%7D)`.
 * Wrapping the URL in `<>` ends the autolink explicitly, so Roam writes the URL back bare.
 *
 * Only this shape needs it. A bare URL and `![](url)` already survive the round trip.
 */

/**
 * Every component that carries a bare URL in this shape, not only the ones an imported
 * asset can become: the mangling is the parser's and hits all of them.
 */
const MEDIA_KEYWORDS = "pdf|audio|video|iframe|youtube";

/** Roam accepts both spellings. */
const MEDIA_KEYWORD_PATTERN = String.raw`\[\[(?:${MEDIA_KEYWORDS})\]\]|${MEDIA_KEYWORDS}`;

/**
 * Deliberately not the class the identically named pattern in `rewriteAssetLinks.ts` uses:
 * `}}` ends the match here, so parentheses need not. They come back percent-encoded, so a
 * reader sees `a%28b%29.pdf` where the author wrote `a(b).pdf`, which beats a broken embed.
 * Square brackets stay excluded: they diverge the same way the braces do above, and
 * wrapping cannot save them.
 *
 * Excluding `<` and `>` is what makes this idempotent: a wrapped embed cannot match.
 */
const URL_PATTERN = String.raw`https?://[^\s<>\[\]{}"']+`;

/** Whitespace is captured rather than normalised, so a rewrite costs the two brackets only. */
const MEDIA_EMBED = new RegExp(
  String.raw`\{\{(${MEDIA_KEYWORD_PATTERN}):([^\S\n]*)(${URL_PATTERN})([^\S\n]*)\}\}`,
  "g",
);

/**
 * Applied to the whole markdown rather than where embeds are rendered: an import passes
 * through every embed it finds no asset row for, and those are mangled the same way.
 *
 * An embed inside a code block or code span gains a visible `<>`. Accepted: cosmetic
 * there, where mangling is not.
 */
export const protectMediaEmbeds = (markdown: string): string =>
  markdown.replace(MEDIA_EMBED, (_match: string, ...args: unknown[]) => {
    const [keyword, before, url, after] = args as string[];
    return `{{${keyword}:${before}<${url}>${after}}}`;
  });

