96	  client,
97	  sharedNode,
98	  markdown,
99	}: {
100	  client: DGSupabaseClient;
101	  sharedNode: SharedNode;
102	  markdown: string;
103	}): Promise<{ markdown: string; report: AssetImportReport }> => {
