105	
106	  const references = await fetchNodeReferences({ client, sharedNode });
107	  if (!references.length) return { markdown, report: emptyReport() };
108	
109	  // Locators come from the rewriter's own reading of the text. Re-deriving the spellings a
110	  // path might take cannot work: a note writes `fig#1.png` as `fig%231.png`, and
111	  // `encodeURI` leaves `#` alone, so such a filter drops assets the rewrite would resolve.
112	  const resolvable = new Set(
113	    collectAssetLocators(markdown).flatMap(lookupCandidates),
114	  );
115	
116	  // Only the references this content makes, since a copy is permanent. A row outlives its
117	  // locator when `publishNodeAssets` fails to clean it up, or when the asset was
118	  // referenced only in the stripped frontmatter or title heading.
119	  const referenced = references.filter(({ filepath }) =>
120	    resolvable.has(filepath),
121	  );
122	  if (!referenced.length) return { markdown, report: emptyReport() };
123	
124	  const resolved: ResolvedAsset[] = [];
125	  const report = emptyReport();
126	  /**
127	   * The copy each hash resolved to in this run. A second locator for identical bytes takes
128	   * the URL from here rather than from the registry, whose write is best-effort: when it
129	   * fails, asking again would upload the same bytes a second time, permanently.
130	   *
131	   * `mirrored` and `reused` therefore count distinct blobs, and counting the second locator
132	   * as `reused` would claim this graph already held what it had just fetched. `skipped` and
133	   * `failed` stay per locator, since each is a place the page degraded.
134	   */
135	  const urlByHash = new Map<string, string>();
136	  /**
137	   * Oversize is a property of the bytes, so it is decided once per hash: asking again
138	   * costs a round trip, or a second download of a blob already known to be too big. A
139	   * throw is not cached, since it may be transient.
140	   */
141	  const skippedByHash = new Map<string, { size: number; limit: number }>();
142	
143	  // Sequential on purpose: the registry check that stops identical bytes uploading twice
144	  // races if these run together.
145	  for (const reference of referenced) {
146	    const alreadySkipped = skippedByHash.get(reference.filehash);
147	    if (alreadySkipped) {
148	      report.skipped.push({
149	        sourceLocator: reference.filepath,
150	        reason: "too-large",
151	        ...alreadySkipped,
152	      });
153	      continue;
154	    }
155	    const alreadyResolved = urlByHash.get(reference.filehash);
156	    if (alreadyResolved) {
157	      resolved.push({
158	        sourceLocator: reference.filepath,
159	        url: alreadyResolved,
160	        sourcePath: reference.source_path,
161	      });
162	      continue;
163	    }
164	    try {
165	      const result = await mirrorAssetToRoamStorage({
166	        client,
167	        contentHash: reference.filehash,
168	        sourcePath: reference.source_path,
169	      });
170	      if (result.status === "skipped") {
171	        skippedByHash.set(reference.filehash, {
172	          size: result.size,
173	          limit: result.limit,
174	        });
175	        report.skipped.push({
176	          sourceLocator: reference.filepath,
177	          reason: result.reason,
178	          size: result.size,
179	          limit: result.limit,
180	        });
181	        continue;
182	      }
183	      urlByHash.set(reference.filehash, result.url);
184	      if (result.status === "mirrored") report.mirrored += 1;
185	      else report.reused += 1;
186	      resolved.push({
187	        sourceLocator: reference.filepath,
188	        url: result.url,
189	        sourcePath: reference.source_path,
190	      });
191	    } catch (error) {
192	      report.failed.push({
193	        sourceLocator: reference.filepath,
194	        message: getErrorMessage(error),
195	      });
196	    }
197	  }
198	
199	  const unresolved = [
200	    ...report.failed.map(
201	      ({ sourceLocator }): UnresolvedAsset => ({
202	        sourceLocator,
203	        marker: FAILED_IMPORT_MARKER,
204	      }),
205	    ),
206	    ...report.skipped.map(
207	      ({ sourceLocator }): UnresolvedAsset => ({
208	        sourceLocator,
209	        marker: TOO_LARGE_MARKER,
210	      }),
211	    ),
212	  ];
213	
214	  return {
215	    markdown: rewriteAssetLinks({ markdown, assets: resolved, unresolved }),
216	    report,
217	  };
218	};
