162	  // oversized asset costs one small request instead of the download this cap exists to
163	  // prevent. Where the metadata omits it, the check moves after the download.
164	  //
165	  // An info failure is metadata this object does not carry, not a reason to abort: the
166	  // pre-check is only an optimisation, and the post-download check enforces the cap on
167	  // its own. Where info fails for a reason that matters — a missing object, a policy that
168	  // denies reads — the download fails next and reports it there.
169	  const { data: info } = await storage.info(contentHash);
170	  const tooLarge = (size: number): SkippedMirror => ({
171	    status: "skipped",
172	    contentHash,
173	    reason: "too-large",
174	    size,
175	    limit: MAX_ASSET_BYTES,
176	  });
177	  if (info?.size !== undefined && isAssetTooLarge(info.size))
178	    return tooLarge(info.size);
179	
180	  const { data: blob, error: downloadError } =
