192	  );
193	
194	  // Upload first, then record. A placeholder written beforehand would carry no URL, so a
195	  // later run could neither reuse the upload nor find it, and Roam exposes no way to list
196	  // a graph's files. A crash between the two leaves one orphaned file, which Roam's own
197	  // documentation treats as normal.
198	  const uploadReturn = await window.roamAlphaAPI.file.upload({
199	    file,
200	    // One import mirrors one file per distinct hash across every node it brings in, so
201	    // the default toast would fire dozens of times at a user who asked for one import.
202	    toast: { hide: true },
