215	    await recordMirroredAsset({ contentHash, url });
216	  } catch (error) {
217	    console.warn(
218	      `Copied an asset into this graph but could not record it in the asset registry, so it will be uploaded again on the next import: ${getErrorMessage(error)}`,
219	    );
220	  }
221	  return { status: "mirrored", contentHash, url };
222	};
